-- Students can see parent-created assignments/portfolio records, but cannot edit them directly.
drop policy if exists "students read own homeschool records" on homeschool_records;
create policy "students read own homeschool records"
on homeschool_records for select
to authenticated
using (
  exists (
    select 1 from students s
    where s.id = homeschool_records.student_id
      and s.student_user_id = auth.uid()
  )
);
